import type { CheckboxProps } from "./checkbox.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import { getExcludedDOMProps, getStyleSlots } from "@system";
import * as RadixCheckbox from "@radix-ui/react-checkbox";
import styled from "@emotion/styled";
import { useMemo } from "react";

const componentName = "Checkbox";

export const CheckboxClasses = {
  root: "exp-textura_checkbox",
  indicator: "exp-textura_checkbox_indicator",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    root: {
      border: `${theme.toRem(theme.border.width.sm)} solid ${theme.inputSelect.radio.off.critical.color.content.enabled}`,
    },
    hover: {
      borderColor: theme.inputSelect.radio.off.critical.color.content.hover,
    },
    active: {
      borderColor: theme.inputSelect.radio.off.critical.color.content.pressed,
    },
    disabled: {
      borderColor: theme.inputSelect.radio.off.critical.color.content.disabled,
      backgroundColor: theme.inputSelect.radio.on.critical.color.background.disabled,
    },
    checked: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.enabled,
    },
    checkedHover: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.hover,
    },
    checkedActive: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.pressed,
    },
    checkedDisabled: {
      backgroundColor: theme.inputSelect.radio.on.critical.color.content.disabled,
    },
  },
  inverse: {
    root: {
      border: `${theme.toRem(theme.border.width.sm)} solid ${theme.inputSelect.radio.off.inverse.color.content.enabled}`,
    },
    hover: {
      borderColor: theme.inputSelect.radio.off.inverse.color.content.hover,
    },
    active: {
      borderColor: theme.inputSelect.radio.off.inverse.color.content.pressed,
    },
    disabled: {
      borderColor: theme.inputSelect.radio.off.inverse.color.content.disabled,
      backgroundColor: theme.inputSelect.radio.on.inverse.color.background.disabled,
    },
    checked: {
      color: theme.color.content.strong,
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.enabled,
    },
    checkedHover: {
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.hover,
    },
    checkedActive: {
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.pressed,
    },
    checkedDisabled: {
      backgroundColor: theme.inputSelect.radio.on.inverse.color.content.disabled,
    },
  },
});

const generateStyles = (props: CheckboxProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<CheckboxProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    all: "unset",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "pointer",
    backgroundColor: theme.inputSelect.checkbox.off.default.color.background.enabled,
    border: `${theme.toRem(theme.border.width.sm)} solid ${theme.inputSelect.checkbox.off.default.color.content.enabled}`,
    width: theme.toRem(theme.spacing[16]),
    height: theme.toRem(theme.spacing[16]),

    "&:focus-visible": {
      ...styleSlots?.focus,
    },

    "&:hover": {
      borderColor: theme.inputSelect.checkbox.off.default.color.content.hover,
      ...styleSlots?.hover,
    },

    "&:active:not([disabled])": {
      backgroundColor: theme.inputSelect.checkbox.off.default.color.background.pressed,
      borderColor: theme.inputSelect.checkbox.off.default.color.content.pressed,
      ...styleSlots?.active,
    },

    [`.${CheckboxClasses.indicator}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      pointerEvents: "none",
      "& svg": {
        width: theme.toRem(10),
        height: theme.toRem(10),
      },
      ...styleSlots?.indicator,
    },

    "&[data-disabled]": {
      cursor: "not-allowed",
      background: theme.inputSelect.checkbox.off.default.color.background.disabled,
      border: `${theme.toRem(theme.border.width.sm)} solid ${theme.inputSelect.checkbox.off.default.color.content.disabled}`,
      color: theme.color.content.inverseStrong,
      ...styleSlots?.disabled,
    },

    "&[data-state=checked], &[data-state=indeterminate]": {
      backgroundColor: theme.inputSelect.checkbox.on.default.color.content.enabled,
      border: "none",
      color: theme.color.content.inverseStrong,

      "&:hover:not([disabled])": {
        backgroundColor: theme.inputSelect.checkbox.on.default.color.content.hover,
        ...styleSlots?.checkedHover,
      },

      // Ensure active takes precedence over hover when both are applied
      "&:active, &:hover:active:not([disabled])": {
        backgroundColor: theme.inputSelect.checkbox.on.default.color.content.pressed,
        ...styleSlots?.checkedActive,
      },

      "&[data-disabled]": {
        background: theme.inputSelect.checkbox.on.default.color.content.disabled,
        ...styleSlots?.checkedDisabled,
      },

      ...styleSlots?.checked,
    },

    "&[data-state=indeterminate]": {
      ...styleSlots?.indeterminate,
    },

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledCheckbox = styled(RadixCheckbox.Root, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<CheckboxProps>((props) => generateStyles(props));

export const StyledCheckboxVisual = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<CheckboxProps>((props) => generateStyles(props));
